-- TEST project only (Guy, the walkthrough Q40, Q48): the made-up plans are deleted, and two demo children (c6, c7 of therapist-test@) get a plan of the new kind
-- with a month of data for the spiral. Run after scheduling-v44.sql and scheduling-v44-bank.sql. Safe to run again. Generated by tools/test-demo-sql.py.
do $$
declare ins uuid; th uuid; k int;
begin
  delete from public.goal_scale where true; delete from public.intervention_feedback where true; delete from public.plan_videos where true;
  delete from public.child_plan_versions where true; delete from public.child_plans where true;
  select id into ins from public.staff where kind = 'instructor' and active order by sort_order nulls last limit 1;
  select staff_id into th from public.staff_private where email = 'therapist-test@merkaz-cherum.local';
  perform set_config('mercury.publishing', 'on', true);
  for k in 1..10 loop insert into public.observations (child_id, author, text, goal_id, target_id, valence, created_at, seen_at) values ('c6', ins, 'דוגמה: תצפית על היעד', 'demo-reg-calm-tool', 't1', case when k % 3 = 0 then 'difficulty' else 'success' end, now() - (k * 2 || ' days')::interval, now()); end loop;
  for k in 1..10 loop insert into public.observations (child_id, author, text, goal_id, target_id, valence, created_at, seen_at) values ('c6', ins, 'דוגמה: תצפית על היעד', 'demo-reg-calm-tool', 't3', case when k % 3 = 0 then 'difficulty' else 'success' end, now() - (k * 2 || ' days')::interval, now()); end loop;
  for k in 1..10 loop insert into public.observations (child_id, author, text, goal_id, target_id, valence, created_at, seen_at) values ('c7', ins, 'דוגמה: תצפית על היעד', 'demo-safe-turn-adult', 't1', case when k % 3 = 0 then 'difficulty' else 'success' end, now() - (k * 2 || ' days')::interval, now()); end loop;
  for k in 1..10 loop insert into public.observations (child_id, author, text, goal_id, target_id, valence, created_at, seen_at) values ('c7', ins, 'דוגמה: תצפית על היעד', 'demo-safe-turn-adult', 't2', case when k % 3 = 0 then 'difficulty' else 'success' end, now() - (k * 2 || ' days')::interval, now()); end loop;
  perform set_config('mercury.publishing', 'off', true);
end $$;
select 'test plans reset' as part, 'ok' as result, (select count(*) from public.child_plans) as plans;
