  insert into public.child_plans (child_id, draft, published, published_version, published_at, published_by, review_date) values ('c6', '{"summary": "דוגמה: נועם הגיע לפני חודשיים. כרגע הכי חשוב לעזור לו להירגע ברגעי כעס, בעזרת כלי שבחר.", "avoid": "לא להרים את הקול; לא לשלוח לפינה כעונש", "calm": "קופסת ההרגעה, נשימת בלון", "gender": "m", "goals": [{"id": "demo-reg-calm-tool", "title": "להירגע בעזרת כלי הרגעה", "theme": "", "library_id": null, "status": "focus", "focus": true, "targets_list": [{"id": "t1", "text": "בוחר/ת כלי מקופסת ההרגעה ומשתמש/ת בו עם תזכורת של מבוגר", "staff": "משתמש/ת בכלי מהקופסה כשמזכירים לו/לה", "scale": ["מתפרץ/ת ולא מגיע/ה לכלי", "מגיע/ה לכלי רק אחרי שנרגע/ת", "משתמש/ת בכלי עם מבוגר צמוד", "משתמש/ת בכלי אחרי תזכורת קצרה", "בוחר/ת כלי בעצמו/בעצמה בזמן"], "now": 2, "target": 4}, {"id": "t3", "text": "משתמש/ת בנשימה איטית (בלון, נר) ברגע של כעס", "staff": "עושה את נשימת הבלון כשכועס/ת", "scale": ["לא מסכים/ה", "עושה רק במשחק", "עושה עם מבוגר שנושם איתו/איתה", "עושה אחרי תזכורת", "עושה לבד"], "now": 2, "target": 4}], "interventions_list": [{"id": "i1", "name": "קופסת הרגעה אישית", "what": "מכינים יחד קופסה עם 3–4 כלים שהילד/ה בחר/ה (כדור לחיץ, תמונה, מוזיקה), ומתרגלים בזמן רגוע", "why": "כלי שהילד/ה בחר/ה בעצמו/בעצמה עובד טוב יותר מכלי שקיבל/ה", "freq": "מכינים פעם אחת; מתרגלים פעמיים בשבוע", "approach": "ויסות חושי", "sentences": ["איזה כלי יעזור לך עכשיו?"]}, {"id": "i2", "name": "מד הרגשות", "what": "מד צבעוני מ-1 עד 5. שואלים כמה חזק זה עכשיו, ומה עושים בכל מדרגה", "why": "מדידה הופכת רגש מציף למשהו שאפשר לטפל בו", "freq": "פעמיים ביום, ובכל רגע קשה", "approach": "ARC", "sentences": ["כמה חזק זה עכשיו, מ-1 עד 5?"]}, {"id": "i4", "name": "נשימת בלון", "what": "שואפים כאילו מנפחים בלון בבטן, ונושפים לאט. מתרגלים במשחק, ובכעס עושים יחד", "why": "נשימה איטית מורידה את העוררות של הגוף", "freq": "פעם ביום, 3 דקות, וברגע של כעס", "approach": "TF-CBT", "sentences": ["בוא/י ננפח את הבלון יחד"]}], "strengths": ["שליטה עצמית", "התמדה"], "planet_id": null, "why_staff": "להשתמש בדרך הרגעה שבחר/ה, עם מבוגר או לבד, כשהרגש חזק", "review_date": null, "bank": {"id": null, "age": "5-8"}, "targets": "משתמש/ת בכלי מהקופסה כשמזכירים לו/לה\nעושה את נשימת הבלון כשכועס/ת", "interventions": "• קופסת הרגעה אישית: מכינים יחד קופסה עם 3–4 כלים שהילד/ה בחר/ה (כדור לחיץ, תמונה, מוזיקה), ומתרגלים בזמן רגוע\n• מד הרגשות: מד צבעוני מ-1 עד 5. שואלים כמה חזק זה עכשיו, ומה עושים בכל מדרגה\n• נשימת בלון: שואפים כאילו מנפחים בלון בבטן, ונושפים לאט. מתרגלים במשחק, ובכעס עושים יחד", "sentences": "איזה כלי יעזור לך עכשיו?\nכמה חזק זה עכשיו, מ-1 עד 5?\nבוא/י ננפח את הבלון יחד"}]}'::jsonb, '{"summary": "דוגמה: נועם הגיע לפני חודשיים. כרגע הכי חשוב לעזור לו להירגע ברגעי כעס, בעזרת כלי שבחר.", "avoid": "לא להרים את הקול; לא לשלוח לפינה כעונש", "calm": "קופסת ההרגעה, נשימת בלון", "gender": "m", "goals": [{"id": "demo-reg-calm-tool", "title": "להירגע בעזרת כלי הרגעה", "theme": "", "library_id": null, "status": "focus", "focus": true, "targets_list": [{"id": "t1", "text": "בוחר/ת כלי מקופסת ההרגעה ומשתמש/ת בו עם תזכורת של מבוגר", "staff": "משתמש/ת בכלי מהקופסה כשמזכירים לו/לה", "scale": ["מתפרץ/ת ולא מגיע/ה לכלי", "מגיע/ה לכלי רק אחרי שנרגע/ת", "משתמש/ת בכלי עם מבוגר צמוד", "משתמש/ת בכלי אחרי תזכורת קצרה", "בוחר/ת כלי בעצמו/בעצמה בזמן"], "now": 2, "target": 4}, {"id": "t3", "text": "משתמש/ת בנשימה איטית (בלון, נר) ברגע של כעס", "staff": "עושה את נשימת הבלון כשכועס/ת", "scale": ["לא מסכים/ה", "עושה רק במשחק", "עושה עם מבוגר שנושם איתו/איתה", "עושה אחרי תזכורת", "עושה לבד"], "now": 2, "target": 4}], "interventions_list": [{"id": "i1", "name": "קופסת הרגעה אישית", "what": "מכינים יחד קופסה עם 3–4 כלים שהילד/ה בחר/ה (כדור לחיץ, תמונה, מוזיקה), ומתרגלים בזמן רגוע", "why": "כלי שהילד/ה בחר/ה בעצמו/בעצמה עובד טוב יותר מכלי שקיבל/ה", "freq": "מכינים פעם אחת; מתרגלים פעמיים בשבוע", "approach": "ויסות חושי", "sentences": ["איזה כלי יעזור לך עכשיו?"]}, {"id": "i2", "name": "מד הרגשות", "what": "מד צבעוני מ-1 עד 5. שואלים כמה חזק זה עכשיו, ומה עושים בכל מדרגה